    #[test]
    fn back_no_target_authority_graph_requires_slot_registry_manifest_within_physical_manifest() {
        const RED: &str =
            "RED: no-target slot proof requires registry manifest within physical manifest";

        let (mut app, router, request, owner) =
            prepare_nested_back_no_target_authority_graph_fixture();
        let (slot_entity, node_component, expected, registry_manifest) = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the real nested fixture retains its exact entry");
            let active = entry
                .active
                .as_ref()
                .expect("the real nested fixture retains its current owner");
            assert_eq!(active.child_slots().len(), 1);
            let slot = &active.child_slots()[0];
            let mut expected_support_relationships = slot.expected_anchor_children().to_vec();
            expected_support_relationships.sort_by_key(|entity| entity.to_bits());
            let expected = BackNoTargetAuthorityGraphSlotProjection {
                claim: slot.slot_claim().clone(),
                binding: ProvenEmptyChildSlotBindingProjection {
                    parent: slot.parent().clone(),
                    outlet: slot.outlet().clone(),
                    slot_id: slot.slot_id(),
                    anchor_claim: slot.anchor_claim().clone(),
                    expected_support_relationships,
                },
            };
            let node_component = world
                .components()
                .component_id::<Node>()
                .expect("the real committed child slot registers Node");
            let record = world
                .resource::<RouteEntityRegistry>()
                .record(slot.slot())
                .expect("the real child slot retains its registry record");
            assert_eq!(record.claim(), expected.claim);
            assert!(
                record.manifest().component_ids().contains(&node_component),
                "Node must be a real registry manifest requirement before the perturbation"
            );
            assert!(
                ComponentManifest::from_world(world, slot.slot())
                    .is_some_and(|physical| physical == *record.manifest()),
                "the real child slot must begin with an exact physical manifest"
            );
            (
                slot.slot(),
                node_component,
                expected,
                record.manifest().clone(),
            )
        };

        assert!(
            app.world().get::<Node>(slot_entity).is_some(),
            "the single-variable perturbation requires the real child-slot Node"
        );
        app.world_mut().entity_mut(slot_entity).remove::<Node>();

        let observed = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the manifest perturbation retains its exact entry");
            let active = entry
                .active
                .as_ref()
                .expect("the manifest perturbation retains its current owner");
            let slot = active
                .child_slots()
                .iter()
                .find(|slot| slot.slot() == slot_entity)
                .expect("the owner still retains the exact committed child slot");
            let registry = world.resource::<RouteEntityRegistry>();
            let record = registry
                .record(slot_entity)
                .expect("the physical mutation cannot remove the registry record");
            assert_eq!(record.claim(), expected.claim);
            assert_eq!(
                record.owner(),
                &RegistryOwner::Committed(EntityOwner::ChildSlot {
                    parent: expected.binding.parent.clone(),
                    outlet: expected.binding.outlet.clone(),
                    slot: expected.binding.slot_id,
                })
            );
            assert_eq!(record.lifecycle(), EntityLifecycle::Active);
            assert_eq!(record.manifest(), &registry_manifest);
            assert_eq!(
                world.get::<RouteOwnershipSeal>(slot_entity),
                Some(&RouteOwnershipSeal::new(expected.claim.seal()))
            );
            assert_eq!(
                world.get::<ChildSlotLifecycle>(slot_entity),
                Some(&ChildSlotLifecycle::Active)
            );
            assert!(
                world
                    .get::<ChildSlotAuthority>(slot_entity)
                    .is_some_and(|authority| {
                        authority.parent() == &expected.binding.parent
                            && authority.outlet() == &expected.binding.outlet
                            && authority.slot() == expected.binding.slot_id
                    }),
                "the ChildSlot authority identity and binding must remain exact"
            );
            assert_eq!(
                world.get::<ChildOf>(slot_entity).map(ChildOf::parent),
                Some(slot.anchor())
            );
            let parent = active
                .frames()
                .iter()
                .find(|frame| frame.frame() == &expected.binding.parent)
                .expect("the exact child-slot parent frame remains owner-held");
            assert!(
                parent
                    .outlet(&expected.binding.outlet)
                    .is_some_and(|outlet| {
                        outlet.anchor() == slot.anchor()
                            && outlet.anchor_claim() == &expected.binding.anchor_claim
                    })
            );
            assert!(
                expected
                    .binding
                    .expected_support_relationships
                    .iter()
                    .all(|entity| {
                        world
                            .get::<Children>(slot.anchor())
                            .is_some_and(|children| children.contains(entity))
                    }),
                "the exact anchor support relationships must remain present"
            );
            assert!(cleanup_claim_has_exact_authority(world, &expected.claim));
            assert!(cleanup_claim_has_exact_authority(
                world,
                &expected.binding.anchor_claim
            ));
            let observed =
                observe_back_no_target_authority_graph_slot(world, registry, active, slot);
            assert_eq!(observed.slot.registry_claim, Some(expected.claim.clone()));
            assert_eq!(
                observed.slot.registry_manifest,
                Some(record.manifest().clone())
            );
            assert_eq!(world.get::<Node>(slot_entity), None);
            let physical_manifest = observed
                .slot
                .physical_manifest
                .as_ref()
                .expect("the committed child-slot Entity still has a physical manifest");
            let missing_required = record
                .manifest()
                .component_ids()
                .iter()
                .copied()
                .filter(|component| !physical_manifest.component_ids().contains(component))
                .collect::<Vec<_>>();
            assert_eq!(
                missing_required,
                vec![node_component],
                "Node must be the only registry requirement absent from the physical manifest"
            );
            observed
        };

        let (
            world_before,
            registry_before,
            engine_before,
            history_before,
            active_frames_before,
            active_slots_before,
            issuer_before,
            requests_before,
            public_router_before,
            public_request_before,
        ) = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the manifest-drift fixture retains its exact entry");
            let host = entry
                .host
                .as_ref()
                .expect("the manifest-drift fixture retains its exact host");
            let active = entry
                .active
                .as_ref()
                .expect("the manifest-drift fixture retains its current owner");
            let snapshots = world.resource::<RouterSnapshots>();
            let public_request = match snapshots.request(router, request) {
                crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                crate::snapshots::RequestLookup::NotRetained => {
                    panic!("the accepted no-target Back remains retained")
                }
                crate::snapshots::RequestLookup::Unknown => {
                    panic!("the accepted no-target Back remains publicly visible")
                }
            };
            (
                ProjectionlessObservedProjection::capture(world, vec![host.host]),
                world.resource::<RouteEntityRegistry>().records().to_vec(),
                entry.engine.snapshot(),
                entry.engine.history().clone(),
                active
                    .frames()
                    .iter()
                    .map(|frame| {
                        (
                            frame.frame().clone(),
                            frame.shell(),
                            frame.mount_binding().clone(),
                            frame.claims().cloned().collect::<Vec<_>>(),
                        )
                    })
                    .collect::<Vec<_>>(),
                active
                    .child_slots()
                    .iter()
                    .map(|slot| {
                        (
                            slot.slot_claim().clone(),
                            slot.parent().clone(),
                            slot.outlet().clone(),
                            slot.anchor_claim().clone(),
                            slot.expected_anchor_children().to_vec(),
                        )
                    })
                    .collect::<Vec<_>>(),
                entry
                    .back_capacity_issuer
                    .as_ref()
                    .expect("the exact entry retains its capacity issuer")
                    .semantic_snapshot_for_test(),
                entry.requests.clone(),
                snapshots
                    .get(router)
                    .expect("the exact router retains its public snapshot")
                    .clone(),
                public_request,
            )
        };
        let capacity_before = owner.capacity.capacity_identity_for_test();

        let outcome = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the exact entry receives the child-slot manifest proof");
            freeze_back_no_target_proven_empty(world, entry, owner)
        };
        let returned_owner = match outcome {
            BackNoTargetPhysicalFreezeOutcome::Indeterminate { owner, evidence } => {
                assert_eq!(evidence.request, request);
                match evidence.reason {
                    BackNoTargetPhysicalIndeterminateReason::AuthorityGraph(evidence) => {
                        assert!(
                            evidence.projection.slots.contains(&expected),
                            "graph evidence must retain the exact owner-held child slot"
                        );
                        match evidence.violation {
                            BackNoTargetAuthorityGraphViolation::SlotBoundaryDrift {
                                expected: observed_expected,
                                observed: observed_projection,
                            } => {
                                assert_eq!(observed_expected, expected);
                                assert_eq!(observed_projection, observed);
                            }
                            _ => panic!("{RED}"),
                        }
                    }
                    _ => panic!("{RED}"),
                }
                owner
            }
            BackNoTargetPhysicalFreezeOutcome::ProvenEmpty(_) => panic!("{RED}"),
        };
        assert_eq!(returned_owner.request, request);
        assert_eq!(
            returned_owner.capacity.capacity_identity_for_test(),
            capacity_before,
            "slot-manifest drift must return the whole original preparation owner"
        );

        let world = app.world();
        let navigation = world.resource::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("slot-manifest rejection cannot remove the router entry");
        let host = entry
            .host
            .as_ref()
            .expect("slot-manifest rejection cannot remove the exact host");
        let active = entry
            .active
            .as_ref()
            .expect("slot-manifest rejection cannot consume the current owner");
        assert_eq!(
            observe_back_no_target_authority_graph_slot(
                world,
                world.resource::<RouteEntityRegistry>(),
                active,
                active
                    .child_slots()
                    .iter()
                    .find(|slot| slot.slot() == slot_entity)
                    .expect("slot-manifest rejection retains the exact child slot"),
            ),
            observed,
            "slot-manifest rejection must preserve the exact observed physical drift"
        );
        assert!(
            ProjectionlessObservedProjection::capture(world, vec![host.host]) == world_before,
            "slot-manifest rejection must be World zero-write"
        );
        assert_eq!(
            world.resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(entry.engine.snapshot(), engine_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(
            active
                .frames()
                .iter()
                .map(|frame| {
                    (
                        frame.frame().clone(),
                        frame.shell(),
                        frame.mount_binding().clone(),
                        frame.claims().cloned().collect::<Vec<_>>(),
                    )
                })
                .collect::<Vec<_>>(),
            active_frames_before
        );
        assert_eq!(
            active
                .child_slots()
                .iter()
                .map(|slot| {
                    (
                        slot.slot_claim().clone(),
                        slot.parent().clone(),
                        slot.outlet().clone(),
                        slot.anchor_claim().clone(),
                        slot.expected_anchor_children().to_vec(),
                    )
                })
                .collect::<Vec<_>>(),
            active_slots_before
        );
        assert_eq!(
            entry
                .back_capacity_issuer
                .as_ref()
                .expect("slot-manifest rejection retains the exact capacity issuer")
                .semantic_snapshot_for_test(),
            issuer_before
        );
        assert_eq!(entry.requests, requests_before);
        let snapshots = world.resource::<RouterSnapshots>();
        assert_eq!(
            snapshots
                .get(router)
                .expect("slot-manifest rejection retains the public router snapshot"),
            &public_router_before
        );
        match snapshots.request(router, request) {
            crate::snapshots::RequestLookup::Found(snapshot) => {
                assert_eq!(snapshot, &public_request_before)
            }
            crate::snapshots::RequestLookup::NotRetained => {
                panic!("slot-manifest rejection cannot evict the accepted no-target Back")
            }
            crate::snapshots::RequestLookup::Unknown => {
                panic!("slot-manifest rejection cannot hide the accepted no-target Back")
            }
        }
    }

    #[test]
    fn back_no_target_authority_graph_rejects_foreign_real_root_mount() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let observed = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let router = install_nested_router(&mut app, observed, true);
        let other_router = install_atomic_router(&mut app, "no-target-root-mount-foreign");
        app.update();

        for location in ["/items/1", "/items/2"] {
            let setup = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .expect("the current nested router accepts each real setup route");
            run_updates_until_succeeded(&mut app, setup);
        }
        let other_request = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .push(other_router, RouteLocation::new("/"))
            .expect("the second real router accepts its root route");
        run_updates_until_succeeded(&mut app, other_request);

        let (request, bound) =
            take_real_bound_back_no_target_from_current_history(&mut app, router);
        let owner = {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the current nested router retains its exact entry");
            match begin_bound_back_no_target(entry, bound) {
                BackNoTargetBeginOutcome::Begun(owner) => owner,
                BackNoTargetBeginOutcome::Permanent(_) => {
                    panic!("the unchanged current source must refreeze before mount mutation")
                }
                BackNoTargetBeginOutcome::CapacityRejected { .. } => {
                    panic!("the real no-target capacity must remain current")
                }
                BackNoTargetBeginOutcome::ReceiverMismatch { .. } => {
                    panic!("the exact current entry must receive its verified no-target owner")
                }
            }
        };
        let (root, foreign_host) = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let current = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the current nested router retains its exact entry");
            let host = current
                .host
                .as_ref()
                .expect("the current nested router retains its exact host");
            let active = current
                .active
                .as_ref()
                .expect("the current nested router retains its active owner");
            let root = active
                .frames()
                .iter()
                .find(|frame| {
                    frame.mount_binding().slot() == host.top_slot
                        && frame.mount_binding().slot_claim() == &host.top_slot_claim
                        && frame.mount_binding().physical_parent() == (host.host, None)
                })
                .map(|frame| frame.frame().clone())
                .expect("the current owner retains one exact host-top root");
            let foreign_host = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == other_router)
                .and_then(|entry| entry.host.as_ref())
                .map(|host| host.host)
                .expect("the second real router retains its app-owned host");
            assert!(world.get_entity(foreign_host).is_ok());
            assert!(
                world
                    .resource::<RouteEntityRegistry>()
                    .record(foreign_host)
                    .is_none(),
                "the second real host must remain app-owned"
            );
            assert_ne!(foreign_host, host.host);
            (root, foreign_host)
        };
        {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let frame = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .and_then(|entry| entry.active.as_mut())
                .and_then(|active| {
                    active
                        .frames_mut_for_test()
                        .iter_mut()
                        .find(|frame| frame.frame() == &root)
                })
                .expect("the owner-only mutation targets the exact current root");
            assert!(
                frame.replace_host_top_mount_host_for_test(foreign_host),
                "the narrow seam must target only the exact HostTop mount"
            );
        }
        let foreign_mount = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the host-metadata mutation retains the current entry");
            let host = entry
                .host
                .as_ref()
                .expect("the host-metadata mutation retains the current host");
            let frame = entry
                .active
                .as_ref()
                .and_then(|active| active.frames().iter().find(|frame| frame.frame() == &root))
                .expect("the host-metadata mutation retains the exact root");
            assert_eq!(frame.mount_binding().slot(), host.top_slot);
            assert_eq!(frame.mount_binding().slot_claim(), &host.top_slot_claim);
            assert_eq!(
                frame.mount_binding().physical_parent(),
                (foreign_host, None)
            );
            let shell_claim = frame
                .claims()
                .find(|claim| {
                    matches!(
                        claim.owner(),
                        RegistryOwner::Committed(EntityOwner::FrameShell(owner))
                            if owner == frame.frame()
                    )
                })
                .expect("the current root retains one exact shell claim");
            let stored_shell_parent = frame
                .cleanup_members()
                .find(|(claim, _)| *claim == shell_claim)
                .map(|(_, parent)| parent)
                .expect("the current root retains its exact shell parent");
            assert_eq!(stored_shell_parent, host.top_slot);
            assert_eq!(
                world
                    .get::<ChildOf>(shell_claim.entity())
                    .map(ChildOf::parent),
                Some(host.top_slot)
            );
            assert!(
                world
                    .resource::<RouteEntityRegistry>()
                    .record(shell_claim.entity())
                    .is_some_and(|record| record.claim() == *shell_claim)
            );
            assert!(cleanup_claim_has_exact_authority(world, shell_claim));
            frame.mount_binding().clone()
        };

        let (
            expected_host,
            world_before,
            registry_before,
            engine_before,
            history_before,
            active_before,
            issuer_before,
            requests_before,
            public_router_before,
            public_request_before,
            other_engine_before,
            other_history_before,
            other_active_before,
            other_issuer_before,
            other_requests_before,
            other_public_router_before,
            other_public_request_before,
        ) = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the current router retains its exact entry");
            let host = entry
                .host
                .as_ref()
                .expect("the current router retains its exact host");
            let active = entry
                .active
                .as_ref()
                .expect("the current router retains its active owner");
            let other_entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == other_router)
                .expect("the second router retains its exact entry");
            let other_host = other_entry
                .host
                .as_ref()
                .expect("the second router retains its exact host");
            let other_active = other_entry
                .active
                .as_ref()
                .expect("the second router retains its active owner");
            let snapshots = world.resource::<RouterSnapshots>();
            let public_request = match snapshots.request(router, request) {
                crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                crate::snapshots::RequestLookup::NotRetained => {
                    panic!("the accepted no-target Back remains retained")
                }
                crate::snapshots::RequestLookup::Unknown => {
                    panic!("the accepted no-target Back remains publicly visible")
                }
            };
            let other_public_request = match snapshots.request(other_router, other_request) {
                crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                crate::snapshots::RequestLookup::NotRetained => {
                    panic!("the second router's root request remains retained")
                }
                crate::snapshots::RequestLookup::Unknown => {
                    panic!("the second router's root request remains publicly visible")
                }
            };
            let capture_active = |active: &RealizedBranch| {
                (
                    active
                        .frames()
                        .iter()
                        .map(|frame| {
                            (
                                frame.frame().clone(),
                                frame.shell(),
                                frame.mount_binding().clone(),
                                frame.claims().cloned().collect::<Vec<_>>(),
                            )
                        })
                        .collect::<Vec<_>>(),
                    active
                        .child_slots()
                        .iter()
                        .map(|slot| {
                            (
                                slot.slot_claim().clone(),
                                slot.parent().clone(),
                                slot.outlet().clone(),
                                slot.anchor_claim().clone(),
                                slot.expected_anchor_children().to_vec(),
                            )
                        })
                        .collect::<Vec<_>>(),
                )
            };
            (
                ProjectionlessHostProjection::from(host),
                ProjectionlessObservedProjection::capture(world, vec![host.host, other_host.host]),
                world.resource::<RouteEntityRegistry>().records().to_vec(),
                entry.engine.snapshot(),
                entry.engine.history().clone(),
                capture_active(active),
                entry
                    .back_capacity_issuer
                    .as_ref()
                    .expect("the current entry retains its capacity issuer")
                    .semantic_snapshot_for_test(),
                entry.requests.clone(),
                snapshots
                    .get(router)
                    .expect("the current router retains its public snapshot")
                    .clone(),
                public_request,
                other_entry.engine.snapshot(),
                other_entry.engine.history().clone(),
                capture_active(other_active),
                other_entry
                    .back_capacity_issuer
                    .as_ref()
                    .expect("the second entry retains its capacity issuer")
                    .semantic_snapshot_for_test(),
                other_entry.requests.clone(),
                snapshots
                    .get(other_router)
                    .expect("the second router retains its public snapshot")
                    .clone(),
                other_public_request,
            )
        };
        let capacity_before = owner.capacity.capacity_identity_for_test();

        let outcome = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the exact entry receives the root-mount proof");
            freeze_back_no_target_proven_empty(world, entry, owner)
        };
        let returned_owner =
            match outcome {
                BackNoTargetPhysicalFreezeOutcome::Indeterminate { owner, evidence } => {
                    assert_eq!(evidence.request, request);
                    match evidence.reason {
                        BackNoTargetPhysicalIndeterminateReason::AuthorityGraph(evidence) => {
                            assert_eq!(evidence.projection.host, expected_host);
                            assert!(evidence.projection.frames.iter().any(|frame| {
                                frame.frame == root && frame.mount == foreign_mount
                            }));
                            assert_eq!(
                                evidence.violation,
                                BackNoTargetAuthorityGraphViolation::RootMountMismatch {
                                    root: root.clone(),
                                }
                            );
                        }
                        _ => panic!("root mount drift must remain typed graph evidence"),
                    }
                    owner
                }
                BackNoTargetPhysicalFreezeOutcome::ProvenEmpty(_) => {
                    panic!("a foreign real root mount cannot prove exact current authority")
                }
            };
        assert_eq!(returned_owner.request, request);
        assert_eq!(
            returned_owner.capacity.capacity_identity_for_test(),
            capacity_before
        );

        let world = app.world();
        let navigation = world.resource::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("root-mount rejection retains the current entry");
        let host = entry
            .host
            .as_ref()
            .expect("root-mount rejection retains the current host");
        let active = entry
            .active
            .as_ref()
            .expect("root-mount rejection retains the current owner");
        let other_entry = navigation
            .entries
            .iter()
            .find(|entry| entry.handle == other_router)
            .expect("root-mount rejection retains the second entry");
        let other_host = other_entry
            .host
            .as_ref()
            .expect("root-mount rejection retains the second host");
        let other_active = other_entry
            .active
            .as_ref()
            .expect("root-mount rejection retains the second active owner");
        let capture_active = |active: &RealizedBranch| {
            (
                active
                    .frames()
                    .iter()
                    .map(|frame| {
                        (
                            frame.frame().clone(),
                            frame.shell(),
                            frame.mount_binding().clone(),
                            frame.claims().cloned().collect::<Vec<_>>(),
                        )
                    })
                    .collect::<Vec<_>>(),
                active
                    .child_slots()
                    .iter()
                    .map(|slot| {
                        (
                            slot.slot_claim().clone(),
                            slot.parent().clone(),
                            slot.outlet().clone(),
                            slot.anchor_claim().clone(),
                            slot.expected_anchor_children().to_vec(),
                        )
                    })
                    .collect::<Vec<_>>(),
            )
        };
        assert!(
            ProjectionlessObservedProjection::capture(world, vec![host.host, other_host.host],)
                == world_before
        );
        assert_eq!(
            world.resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(entry.engine.snapshot(), engine_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(capture_active(active), active_before);
        assert_eq!(
            entry
                .back_capacity_issuer
                .as_ref()
                .expect("root-mount rejection retains the current issuer")
                .semantic_snapshot_for_test(),
            issuer_before
        );
        assert_eq!(entry.requests, requests_before);
        assert_eq!(other_entry.engine.snapshot(), other_engine_before);
        assert_eq!(other_entry.engine.history(), &other_history_before);
        assert_eq!(capture_active(other_active), other_active_before);
        assert_eq!(
            other_entry
                .back_capacity_issuer
                .as_ref()
                .expect("root-mount rejection retains the second issuer")
                .semantic_snapshot_for_test(),
            other_issuer_before
        );
        assert_eq!(other_entry.requests, other_requests_before);
        let snapshots = world.resource::<RouterSnapshots>();
        assert_eq!(
            snapshots
                .get(router)
                .expect("root-mount rejection retains the current public snapshot"),
            &public_router_before
        );
        assert_eq!(
            snapshots
                .get(other_router)
                .expect("root-mount rejection retains the second public snapshot"),
            &other_public_router_before
        );
        match snapshots.request(router, request) {
            crate::snapshots::RequestLookup::Found(snapshot) => {
                assert_eq!(snapshot, &public_request_before)
            }
            _ => panic!("root-mount rejection retains the current public request"),
        }
        match snapshots.request(other_router, other_request) {
            crate::snapshots::RequestLookup::Found(snapshot) => {
                assert_eq!(snapshot, &other_public_request_before)
            }
            _ => panic!("root-mount rejection retains the second public request"),
        }
    }

    #[test]
    fn back_no_target_authority_graph_rejects_disconnected_cycle_at_shell_mount_boundary() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let router = install_deep_nested_router(&mut app);
        app.update();
        for location in ["/sections/a/items/1", "/sections/a/items/2"] {
            let setup = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .expect("the deep router accepts each real three-frame route");
            run_updates_until_succeeded(&mut app, setup);
        }
        let (request, bound) =
            take_real_bound_back_no_target_from_current_history(&mut app, router);
        let owner = {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .expect("the deep router retains its exact entry");
            let active = entry
                .active
                .as_ref()
                .expect("the first Back retains the real deep current branch");
            assert_eq!(active.frames().len(), 3);
            assert_eq!(active.child_slots().len(), 2);
            match begin_bound_back_no_target(entry, bound) {
                BackNoTargetBeginOutcome::Begun(owner) => owner,
                BackNoTargetBeginOutcome::Permanent(_) => {
                    panic!("the unchanged deep source must refreeze before graph mutation")
                }
                BackNoTargetBeginOutcome::CapacityRejected { .. } => {
                    panic!("the real no-target capacity must remain current")
                }
                BackNoTargetBeginOutcome::ReceiverMismatch { .. } => {
                    panic!("the exact deep entry must receive its verified no-target owner")
                }
            }
        };

        let (root, middle, leaf, middle_mount, leaf_mount) = {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the deep router retains its exact entry");
            let host = entry
                .host
                .as_ref()
                .expect("the deep router retains its exact host");
            let active = entry
                .active
                .as_ref()
                .expect("the deep router retains its current owner");
            let root = active
                .frames()
                .iter()
                .find(|frame| {
                    frame.mount_binding().slot() == host.top_slot
                        && frame.mount_binding().slot_claim() == &host.top_slot_claim
                        && frame.mount_binding().physical_parent() == (host.host, None)
                })
                .map(|frame| frame.frame().clone())
                .expect("one exact frame mounts at the host top slot");
            let root_slot = active
                .child_slots()
                .iter()
                .find(|slot| slot.parent() == &root)
                .expect("the exact root owns one real child slot");
            let middle_frame = active
                .frames()
                .iter()
                .find(|frame| frame.mount_binding().matches_mounted_child_slot(root_slot))
                .expect("one exact middle frame enters through the root slot");
            let middle = middle_frame.frame().clone();
            let middle_slot = active
                .child_slots()
                .iter()
                .find(|slot| slot.parent() == &middle)
                .expect("the exact middle frame owns one real child slot");
            let leaf_frame = active
                .frames()
                .iter()
                .find(|frame| {
                    frame
                        .mount_binding()
                        .matches_mounted_child_slot(middle_slot)
                })
                .expect("one exact leaf frame enters through the middle slot");
            (
                root,
                middle,
                leaf_frame.frame().clone(),
                middle_frame.mount_binding().clone(),
                leaf_frame.mount_binding().clone(),
            )
        };
        {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let active = navigation
                .entries
                .iter_mut()
                .find(|entry| entry.handle == router)
                .and_then(|entry| entry.active.as_mut())
                .expect("the owner-only mutation retains the deep current branch");
            active
                .frames_mut_for_test()
                .iter_mut()
                .find(|frame| frame.frame() == &middle)
                .expect("the exact middle frame remains owner-held")
                .replace_mount_binding_for_test(leaf_mount.clone());
            active
                .frames_mut_for_test()
                .iter_mut()
                .find(|frame| frame.frame() == &leaf)
                .expect("the exact leaf frame remains owner-held")
                .replace_mount_binding_for_test(middle_mount.clone());
        }
        let (middle_stored_parent, observed_middle_shell) = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the owner-only swap retains the exact entry");
            let frame = entry
                .active
                .as_ref()
                .and_then(|active| {
                    active
                        .frames()
                        .iter()
                        .find(|frame| frame.frame() == &middle)
                })
                .expect("the owner-only swap retains the exact middle frame");
            let shell_claim = frame
                .claims()
                .find(|claim| {
                    matches!(
                        claim.owner(),
                        RegistryOwner::Committed(EntityOwner::FrameShell(owner))
                            if owner == frame.frame()
                    )
                })
                .expect("the middle frame retains one exact shell claim");
            let stored_parent = frame
                .cleanup_members()
                .find(|(claim, _)| *claim == shell_claim)
                .map(|(_, parent)| parent)
                .expect("the middle frame retains its original shell parent");
            let observed_shell = observe_back_no_target_authority_graph_claim(
                world,
                world.resource::<RouteEntityRegistry>(),
                shell_claim.entity(),
            );
            assert_eq!(frame.mount_binding(), &leaf_mount);
            assert_eq!(stored_parent, middle_mount.slot());
            assert_ne!(stored_parent, leaf_mount.slot());
            assert_eq!(observed_shell.observed_parent, Some(stored_parent));
            (stored_parent, observed_shell)
        };

        let (
            expected_host,
            world_before,
            registry_before,
            engine_before,
            history_before,
            active_before,
            issuer_before,
            requests_before,
            public_router_before,
            public_request_before,
        ) =
            {
                let world = app.world();
                let navigation = world.resource::<RouterNavigation>();
                let entry = navigation
                    .entries
                    .iter()
                    .find(|entry| entry.handle == router)
                    .expect("the cycle fixture retains its exact entry");
                let host = entry
                    .host
                    .as_ref()
                    .expect("the cycle fixture retains its exact host");
                let active = entry
                    .active
                    .as_ref()
                    .expect("the cycle fixture retains its current owner");
                assert!(active.frames().iter().any(|frame| {
                    frame.frame() == &root
                        && frame.mount_binding().slot() == host.top_slot
                        && frame.mount_binding().slot_claim() == &host.top_slot_claim
                }));
                assert!(active.frames().iter().any(|frame| {
                    frame.frame() == &middle && frame.mount_binding() == &leaf_mount
                }));
                assert!(active.frames().iter().any(|frame| {
                    frame.frame() == &leaf && frame.mount_binding() == &middle_mount
                }));
                let snapshots = world.resource::<RouterSnapshots>();
                let public_request = match snapshots.request(router, request) {
                    crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                    crate::snapshots::RequestLookup::NotRetained => {
                        panic!("the accepted no-target Back remains retained")
                    }
                    crate::snapshots::RequestLookup::Unknown => {
                        panic!("the accepted no-target Back remains publicly visible")
                    }
                };
                (
                    ProjectionlessHostProjection::from(host),
                    ProjectionlessObservedProjection::capture(world, vec![host.host]),
                    world.resource::<RouteEntityRegistry>().records().to_vec(),
                    entry.engine.snapshot(),
                    entry.engine.history().clone(),
                    (
                        active
                            .frames()
                            .iter()
                            .map(|frame| {
                                (
                                    frame.frame().clone(),
                                    frame.shell(),
                                    frame.mount_binding().clone(),
                                    frame.claims().cloned().collect::<Vec<_>>(),
                                )
                            })
                            .collect::<Vec<_>>(),
                        active
                            .child_slots()
                            .iter()
                            .map(|slot| {
                                (
                                    slot.slot_claim().clone(),
                                    slot.parent().clone(),
                                    slot.outlet().clone(),
                                    slot.anchor_claim().clone(),
                                    slot.expected_anchor_children().to_vec(),
                                )
                            })
                            .collect::<Vec<_>>(),
                    ),
                    entry
                        .back_capacity_issuer
                        .as_ref()
                        .expect("the exact entry retains its capacity issuer")
                        .semantic_snapshot_for_test(),
                    entry.requests.clone(),
                    snapshots
                        .get(router)
                        .expect("the deep router retains its public snapshot")
                        .clone(),
                    public_request,
                )
            };
        let capacity_before = owner.capacity.capacity_identity_for_test();

        let outcome = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the exact entry receives the boundary-first cycle proof");
            freeze_back_no_target_proven_empty(world, entry, owner)
        };
        let returned_owner =
            match outcome {
                BackNoTargetPhysicalFreezeOutcome::Indeterminate { owner, evidence } => {
                    assert_eq!(evidence.request, request);
                    match evidence.reason {
                        BackNoTargetPhysicalIndeterminateReason::AuthorityGraph(evidence) => {
                            assert_eq!(evidence.projection.host, expected_host);
                            assert!(evidence.projection.frames.iter().any(|frame| {
                                frame.frame == middle && frame.mount == leaf_mount
                            }));
                            assert!(evidence.projection.frames.iter().any(|frame| {
                                frame.frame == leaf && frame.mount == middle_mount
                            }));
                            assert_eq!(
                                evidence.violation,
                                BackNoTargetAuthorityGraphViolation::FrameShellMountBoundaryDrift {
                                    frame: middle.clone(),
                                    mount_slot: leaf_mount.slot(),
                                    stored_parent: middle_stored_parent,
                                    observed_shell: observed_middle_shell.clone(),
                                }
                            );
                        }
                        _ => panic!("the owner-only cycle must reject at the shell-mount boundary"),
                    }
                    owner
                }
                BackNoTargetPhysicalFreezeOutcome::ProvenEmpty(_) => {
                    panic!("a boundary-invalid owner-held cycle cannot prove empty authority")
                }
            };
        assert_eq!(returned_owner.request, request);
        assert_eq!(
            returned_owner.capacity.capacity_identity_for_test(),
            capacity_before
        );

        let world = app.world();
        let navigation = world.resource::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("cycle rejection retains the exact entry");
        let host = entry
            .host
            .as_ref()
            .expect("cycle rejection retains the exact host");
        let active = entry
            .active
            .as_ref()
            .expect("cycle rejection retains the current owner");
        let active_after = (
            active
                .frames()
                .iter()
                .map(|frame| {
                    (
                        frame.frame().clone(),
                        frame.shell(),
                        frame.mount_binding().clone(),
                        frame.claims().cloned().collect::<Vec<_>>(),
                    )
                })
                .collect::<Vec<_>>(),
            active
                .child_slots()
                .iter()
                .map(|slot| {
                    (
                        slot.slot_claim().clone(),
                        slot.parent().clone(),
                        slot.outlet().clone(),
                        slot.anchor_claim().clone(),
                        slot.expected_anchor_children().to_vec(),
                    )
                })
                .collect::<Vec<_>>(),
        );
        assert!(ProjectionlessObservedProjection::capture(world, vec![host.host]) == world_before);
        assert_eq!(
            world.resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(entry.engine.snapshot(), engine_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(active_after, active_before);
        assert_eq!(
            entry
                .back_capacity_issuer
                .as_ref()
                .expect("cycle rejection retains the exact capacity issuer")
                .semantic_snapshot_for_test(),
            issuer_before
        );
        assert_eq!(entry.requests, requests_before);
        let snapshots = world.resource::<RouterSnapshots>();
        assert_eq!(
            snapshots
                .get(router)
                .expect("cycle rejection retains the public router snapshot"),
            &public_router_before
        );
        match snapshots.request(router, request) {
            crate::snapshots::RequestLookup::Found(snapshot) => {
                assert_eq!(snapshot, &public_request_before)
            }
            _ => panic!("cycle rejection retains the public no-target request"),
        }
    }

    #[test]
    fn back_no_target_authority_graph_requires_exact_mount_slot_to_shell_binding() {
        const RED: &str =
            "RED: no-target authority graph requires exact mount-slot to shell binding";

        let (mut app, router, request, owner) =
            prepare_nested_back_no_target_authority_graph_fixture();
        let (frame_version, mount_slot, shell_claim, stored_parent, observed_shell) = {
            let (frame_version, mount_slot, shell_claim, host_top_slot) = {
                let navigation = app.world().resource::<RouterNavigation>();
                let entry = navigation
                    .entries
                    .iter()
                    .find(|entry| entry.handle == router)
                    .expect("the real nested fixture retains its exact entry");
                let host = entry
                    .host
                    .as_ref()
                    .expect("the real nested fixture retains its exact host");
                let active = entry
                    .active
                    .as_ref()
                    .expect("the real nested fixture retains its current owner");
                assert_eq!(active.child_slots().len(), 1);
                let child_slot = &active.child_slots()[0];
                let frame = active
                    .frames()
                    .iter()
                    .find(|frame| frame.mount_binding().matches_mounted_child_slot(child_slot))
                    .expect("one exact nonroot frame enters through the child slot");
                let shell_claim = frame
                    .claims()
                    .find(|claim| {
                        matches!(
                            claim.owner(),
                            RegistryOwner::Committed(EntityOwner::FrameShell(owner))
                                if owner == frame.frame()
                        )
                    })
                    .cloned()
                    .expect("the nonroot frame retains one exact FrameShell claim");
                let stored_shell_parent = frame
                    .cleanup_members()
                    .find(|(claim, _)| *claim == &shell_claim)
                    .map(|(_, parent)| parent)
                    .expect("the owner-held shell retains one exact cleanup parent");
                assert_eq!(stored_shell_parent, child_slot.slot());
                (
                    frame.frame().clone(),
                    child_slot.slot(),
                    shell_claim,
                    host.top_slot,
                )
            };
            let sibling = app
                .world_mut()
                .spawn(bevy_ecs::hierarchy::ChildOf(mount_slot))
                .id();
            assert!(
                app.world()
                    .resource::<RouteEntityRegistry>()
                    .record(sibling)
                    .is_none(),
                "the mount-slot sibling must remain unregistered"
            );
            {
                let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
                let frame = navigation
                    .entries
                    .iter_mut()
                    .find(|entry| entry.handle == router)
                    .and_then(|entry| entry.active.as_mut())
                    .and_then(|active| {
                        active
                            .frames_mut_for_test()
                            .iter_mut()
                            .find(|frame| frame.frame() == &frame_version)
                    })
                    .expect("the owner-only mutation targets the exact nonroot frame");
                frame.replace_shell_parent_for_test(host_top_slot);
            }
            app.world_mut()
                .entity_mut(shell_claim.entity())
                .insert(bevy_ecs::hierarchy::ChildOf(host_top_slot));
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the shell reparent retains the exact entry");
            let active = entry
                .active
                .as_ref()
                .expect("the shell reparent retains the current owner");
            let frame = active
                .frames()
                .iter()
                .find(|frame| frame.frame() == &frame_version)
                .expect("the shell reparent retains the exact nonroot frame");
            assert_eq!(frame.mount_binding().slot(), mount_slot);
            let stored_parent = frame
                .cleanup_members()
                .find(|(claim, _)| *claim == &shell_claim)
                .map(|(_, parent)| parent)
                .expect("the mutated owner retains the shell cleanup member");
            assert_eq!(stored_parent, host_top_slot);
            let observed_shell = observe_back_no_target_authority_graph_claim(
                world,
                world.resource::<RouteEntityRegistry>(),
                shell_claim.entity(),
            );
            assert_eq!(observed_shell.observed_parent, Some(stored_parent));
            assert!(
                world
                    .get::<bevy_ecs::hierarchy::Children>(mount_slot)
                    .is_some_and(|children| children.contains(&sibling)),
                "the unregistered sibling must preserve the mount-slot Children manifest"
            );
            (
                frame_version,
                mount_slot,
                shell_claim,
                stored_parent,
                observed_shell,
            )
        };

        let (
            world_before,
            registry_before,
            engine_before,
            history_before,
            active_before,
            issuer_before,
            requests_before,
            public_router_before,
            public_request_before,
        ) = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the shell-mount fixture retains its exact entry");
            let host = entry
                .host
                .as_ref()
                .expect("the shell-mount fixture retains its exact host");
            let active = entry
                .active
                .as_ref()
                .expect("the shell-mount fixture retains its current owner");
            let snapshots = world.resource::<RouterSnapshots>();
            let public_request = match snapshots.request(router, request) {
                crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                crate::snapshots::RequestLookup::NotRetained => {
                    panic!("the accepted no-target Back remains retained")
                }
                crate::snapshots::RequestLookup::Unknown => {
                    panic!("the accepted no-target Back remains publicly visible")
                }
            };
            (
                ProjectionlessObservedProjection::capture(world, vec![host.host]),
                world.resource::<RouteEntityRegistry>().records().to_vec(),
                entry.engine.snapshot(),
                entry.engine.history().clone(),
                (
                    active
                        .frames()
                        .iter()
                        .map(|frame| {
                            (
                                frame.frame().clone(),
                                frame.shell(),
                                frame.mount_binding().clone(),
                                frame
                                    .cleanup_members()
                                    .map(|(claim, parent)| (claim.clone(), parent))
                                    .collect::<Vec<_>>(),
                            )
                        })
                        .collect::<Vec<_>>(),
                    active
                        .child_slots()
                        .iter()
                        .map(|slot| {
                            (
                                slot.slot_claim().clone(),
                                slot.parent().clone(),
                                slot.outlet().clone(),
                                slot.anchor_claim().clone(),
                                slot.expected_anchor_children().to_vec(),
                            )
                        })
                        .collect::<Vec<_>>(),
                ),
                entry
                    .back_capacity_issuer
                    .as_ref()
                    .expect("the exact entry retains its capacity issuer")
                    .semantic_snapshot_for_test(),
                entry.requests.clone(),
                snapshots
                    .get(router)
                    .expect("the exact router retains its public snapshot")
                    .clone(),
                public_request,
            )
        };
        let capacity_before = owner.capacity.capacity_identity_for_test();

        let outcome = {
            let world = app.world();
            let navigation = world.resource::<RouterNavigation>();
            let entry = navigation
                .entries
                .iter()
                .find(|entry| entry.handle == router)
                .expect("the exact entry receives the shell-mount boundary proof");
            freeze_back_no_target_proven_empty(world, entry, owner)
        };
        let returned_owner = match outcome {
            BackNoTargetPhysicalFreezeOutcome::Indeterminate { owner, evidence } => {
                assert_eq!(evidence.request, request);
                match evidence.reason {
                    BackNoTargetPhysicalIndeterminateReason::AuthorityGraph(evidence) => {
                        assert!(evidence.projection.frames.iter().any(|frame| {
                            frame.frame == frame_version
                                && frame.mount.slot() == mount_slot
                                && frame.claims.contains(&shell_claim)
                        }));
                        match evidence.violation {
                            BackNoTargetAuthorityGraphViolation::FrameShellMountBoundaryDrift {
                                frame,
                                mount_slot: observed_mount_slot,
                                stored_parent: observed_stored_parent,
                                observed_shell: observed_projection,
                            } => {
                                assert_eq!(frame, frame_version);
                                assert_eq!(observed_mount_slot, mount_slot);
                                assert_eq!(observed_stored_parent, stored_parent);
                                assert_eq!(observed_projection, observed_shell);
                            }
                            _ => panic!("{RED}"),
                        }
                    }
                    _ => panic!("{RED}"),
                }
                owner
            }
            BackNoTargetPhysicalFreezeOutcome::ProvenEmpty(_) => panic!("{RED}"),
        };
        assert_eq!(returned_owner.request, request);
        assert_eq!(
            returned_owner.capacity.capacity_identity_for_test(),
            capacity_before
        );

        let world = app.world();
        let navigation = world.resource::<RouterNavigation>();
        let entry = navigation
            .entries
            .iter()
            .find(|entry| entry.handle == router)
            .expect("shell-mount rejection retains the exact entry");
        let host = entry
            .host
            .as_ref()
            .expect("shell-mount rejection retains the exact host");
        let active = entry
            .active
            .as_ref()
            .expect("shell-mount rejection retains the current owner");
        let active_after = (
            active
                .frames()
                .iter()
                .map(|frame| {
                    (
                        frame.frame().clone(),
                        frame.shell(),
                        frame.mount_binding().clone(),
                        frame
                            .cleanup_members()
                            .map(|(claim, parent)| (claim.clone(), parent))
                            .collect::<Vec<_>>(),
                    )
                })
                .collect::<Vec<_>>(),
            active
                .child_slots()
                .iter()
                .map(|slot| {
                    (
                        slot.slot_claim().clone(),
                        slot.parent().clone(),
                        slot.outlet().clone(),
                        slot.anchor_claim().clone(),
                        slot.expected_anchor_children().to_vec(),
                    )
                })
                .collect::<Vec<_>>(),
        );
        assert!(ProjectionlessObservedProjection::capture(world, vec![host.host]) == world_before);
        assert_eq!(
            world.resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(entry.engine.snapshot(), engine_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(active_after, active_before);
        assert_eq!(
            entry
                .back_capacity_issuer
                .as_ref()
                .expect("shell-mount rejection retains the exact capacity issuer")
                .semantic_snapshot_for_test(),
            issuer_before
        );
        assert_eq!(entry.requests, requests_before);
        let snapshots = world.resource::<RouterSnapshots>();
        assert_eq!(
            snapshots
                .get(router)
                .expect("shell-mount rejection retains the public router snapshot"),
            &public_router_before
        );
        match snapshots.request(router, request) {
            crate::snapshots::RequestLookup::Found(snapshot) => {
                assert_eq!(snapshot, &public_request_before)
            }
            _ => panic!("shell-mount rejection retains the public no-target request"),
        }
    }

    #[test]
    fn back_resolution_handoff_foreign_and_duplicate_are_zero_write() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let exact_router =
            install_atomic_router_at_pattern(&mut app, "back-resolution-exact", "/:id");
        let foreign_router =
            install_atomic_router_at_pattern(&mut app, "back-resolution-foreign", "/:id");
        app.update();
        for router in [exact_router, foreign_router] {
            for location in ["/first", "/second"] {
                app.world_mut()
                    .resource_mut::<RouterNavigation>()
                    .push(router, RouteLocation::new(location))
                    .unwrap();
                app.update();
            }
        }
        let exact_request = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(exact_router)
            .expect("the exact router has one real predecessor");
        let foreign_request = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(foreign_router)
            .expect("the foreign router also owns one real accepted capacity");

        let world_before = authority_world_fingerprint(app.world());
        let exact_public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(exact_router)
            .expect("the exact router has a public snapshot")
            .clone();
        let foreign_public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(foreign_router)
            .expect("the foreign router has a public snapshot")
            .clone();

        let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
        let exact_index = navigation
            .entries
            .iter()
            .position(|entry| entry.handle == exact_router)
            .unwrap();
        let foreign_index = navigation
            .entries
            .iter()
            .position(|entry| entry.handle == foreign_router)
            .unwrap();
        let (exact, foreign) = if exact_index < foreign_index {
            let (before, after) = navigation.entries.split_at_mut(foreign_index);
            (&mut before[exact_index], &mut after[0])
        } else {
            let (before, after) = navigation.entries.split_at_mut(exact_index);
            (&mut after[0], &mut before[foreign_index])
        };
        exact.engine.collect();
        let Some(EngineAction::BackResolution(handoff)) = exact.engine.action() else {
            panic!("a real accepted back must yield its raw resolution owner")
        };
        let observed_evidence = handoff.evidence();
        let scope = handoff.scope();
        let reservation_index = exact
            .back_capacity_reservations
            .iter()
            .position(|(_, reservation)| reservation.matches_resolution_scope(&scope))
            .expect("the raw handoff must select its exact accepted capacity owner opaquely");
        let (_, reservation) = exact.back_capacity_reservations.remove(reservation_index);
        let capacity_identity = reservation.capacity_identity_for_test();
        foreign
            .back_capacity_reservations
            .push((reservation.request(), reservation));
        let exact_engine_before = exact.engine.snapshot();
        let foreign_engine_before = foreign.engine.snapshot();
        let exact_request_before = {
            let request = exact.engine.request(exact_request).unwrap();
            (
                request.requested().cloned(),
                request.status().clone(),
                request.trace().to_vec(),
            )
        };
        let foreign_request_before = {
            let request = foreign.engine.request(foreign_request).unwrap();
            (
                request.requested().cloned(),
                request.status().clone(),
                request.trace().to_vec(),
            )
        };

        assert_eq!(
            foreign.validate_back_resolution_evidence(&observed_evidence),
            BackResolutionEvidenceDisposition::Foreign,
            "the exact raw handoff evidence must remain foreign to another router entry"
        );
        assert_eq!(
            foreign
                .back_resolution_evidence_predicate_calls
                .load(Ordering::Relaxed),
            1
        );
        let (reservation, handoff) = match foreign.take_back_resolution_handoff(handoff) {
            TakeBackResolutionOutcome::Mismatch {
                reservation,
                handoff,
                evidence,
            } => {
                assert_eq!(
                    foreign.validate_back_resolution_evidence(&evidence),
                    BackResolutionEvidenceDisposition::Foreign,
                    "foreign mismatch diagnostics must remain foreign to the observing entry"
                );
                (reservation, handoff)
            }
            TakeBackResolutionOutcome::Matched(_) => {
                panic!("a foreign entry must not verify the exact Core handoff")
            }
        };
        assert_eq!(
            foreign
                .back_resolution_evidence_predicate_calls
                .load(Ordering::Relaxed),
            2
        );
        assert_eq!(
            reservation.capacity_identity_for_test(),
            capacity_identity,
            "foreign mismatch must return the complete original bound capacity"
        );
        assert_eq!(exact.engine.snapshot(), exact_engine_before);
        assert_eq!(foreign.engine.snapshot(), foreign_engine_before);
        {
            let request = exact.engine.request(exact_request).unwrap();
            assert_eq!(
                (
                    request.requested().cloned(),
                    request.status().clone(),
                    request.trace().to_vec(),
                ),
                exact_request_before
            );
        }
        {
            let request = foreign.engine.request(foreign_request).unwrap();
            assert_eq!(
                (
                    request.requested().cloned(),
                    request.status().clone(),
                    request.trace().to_vec(),
                ),
                foreign_request_before
            );
        }
        exact.restore_back_capacity_reservation(reservation);

        assert_eq!(
            exact.validate_back_resolution_evidence(&observed_evidence),
            BackResolutionEvidenceDisposition::Current,
            "the exact entry must classify its still-current raw handoff evidence as Current"
        );
        assert_eq!(
            exact
                .back_resolution_evidence_predicate_calls
                .load(Ordering::Relaxed),
            1
        );
        match exact.take_back_resolution_handoff(handoff) {
            TakeBackResolutionOutcome::Matched(bound) => {
                assert_eq!(
                    bound_back_resolution_capacity_identity(&bound),
                    capacity_identity
                );
                assert!(matches!(bound, BoundBackResolutionHandoff::Target(_)));
                assert!(exact.engine.action().is_none());
                assert!(exact.pending_back_resolution_action.is_none());
            }
            TakeBackResolutionOutcome::Mismatch {
                reservation,
                handoff,
                evidence,
            } => {
                exact.restore_back_resolution_mismatch(reservation, handoff, evidence);
                panic!(
                    "the exact entry must preserve complete authority and capacity through a matched handoff"
                )
            }
        }
        assert_eq!(
            exact.validate_back_resolution_evidence(&observed_evidence),
            BackResolutionEvidenceDisposition::ConsumedReplay,
            "the saved exact evidence must become a non-authorizing consumed replay"
        );
        assert_eq!(
            exact
                .back_resolution_evidence_predicate_calls
                .load(Ordering::Relaxed),
            3,
            "Current observation, internal take validation, and explicit replay validation must each call the real predicate exactly once"
        );
        assert_eq!(exact.engine.snapshot(), exact_engine_before);
        drop(navigation);
        assert_eq!(authority_world_fingerprint(app.world()), world_before);
        assert_eq!(
            app.world()
                .resource::<RouterSnapshots>()
                .get(exact_router)
                .unwrap(),
            &exact_public_before
        );
        assert_eq!(
            app.world()
                .resource::<RouterSnapshots>()
                .get(foreign_router)
                .unwrap(),
            &foreign_public_before
        );
    }

    #[test]
    fn back_resolution_pending_owner_blocks_next_collect() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let router = install_atomic_router_at_pattern(&mut app, "back-resolution-collect", "/:id");
        app.update();
        for location in ["/first", "/second"] {
            app.world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .unwrap();
            app.update();
        }
        let (first, second) = {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let first = navigation
                .back(router)
                .expect("the first real back is accepted against the live predecessor");
            let second = navigation
                .back(router)
                .expect("the second real back is accepted while that predecessor is live");
            (first, second)
        };

        collect_navigation_system(app.world_mut());
        drive_navigation_system(app.world_mut());
        publish_snapshots_system(app.world_mut());

        let (core_before, second_before) = {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = &mut navigation.entries[0];
            assert!(
                entry.engine.action().is_none(),
                "the exact target dispatcher moves the physical action into the existing driver"
            );
            assert!(
                entry.pending_back_resolution_action.is_none(),
                "an exact Matched take must not retain the old raw mismatch owner"
            );
            assert!(
                entry.pending_bound_back_resolution.is_none(),
                "Step 8 consumes the exact verified target owner into its single execution stage"
            );
            assert!(matches!(
                entry.pending_back_target_execution.as_ref(),
                Some(PendingBackTargetExecution::Driving(_))
            ));
            assert!(
                entry
                    .pending_commit
                    .as_ref()
                    .is_some_and(|pending| pending.final_task.is_some()),
                "the real root frame report remains paired with the target Driving owner"
            );
            assert!(
                entry
                    .back_capacity_reservations
                    .iter()
                    .all(|(request, _)| *request != first),
                "dispatch retires the first target capacity exactly once"
            );
            let second_view = entry
                .engine
                .request(second)
                .expect("the second accepted request remains retained");
            assert_eq!(second_view.status(), &RequestStatus::Queued);
            let second_before = (
                second_view.requested().cloned(),
                second_view.status().clone(),
                second_view.trace().to_vec(),
            );
            (entry.engine.snapshot(), second_before)
        };
        let (public_router_before, public_first_before, public_second_before) = {
            let snapshots = app.world().resource::<RouterSnapshots>();
            let public_first_before = match snapshots.request(router, first) {
                crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                _ => panic!("the first accepted back has a published request snapshot"),
            };
            let public_second_before = match snapshots.request(router, second) {
                crate::snapshots::RequestLookup::Found(snapshot) => snapshot.clone(),
                _ => panic!("the second accepted back has a published request snapshot"),
            };
            (
                snapshots.get(router).unwrap().clone(),
                public_first_before,
                public_second_before,
            )
        };

        collect_navigation_system(app.world_mut());

        {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = &mut navigation.entries[0];
            assert_eq!(entry.engine.snapshot(), core_before);
            let second_view = entry.engine.request(second).unwrap();
            assert_eq!(
                (
                    second_view.requested().cloned(),
                    second_view.status().clone(),
                    second_view.trace().to_vec(),
                ),
                second_before
            );
            assert!(entry.pending_back_resolution_action.is_none());
            assert!(entry.pending_bound_back_resolution.is_none());
            assert!(matches!(
                entry.pending_back_target_execution.as_ref(),
                Some(PendingBackTargetExecution::Driving(_))
            ));
        }
        {
            let snapshots = app.world().resource::<RouterSnapshots>();
            assert_eq!(snapshots.get(router).unwrap(), &public_router_before);
            assert_eq!(
                snapshots.request(router, first),
                crate::snapshots::RequestLookup::Found(&public_first_before)
            );
            assert_eq!(
                snapshots.request(router, second),
                crate::snapshots::RequestLookup::Found(&public_second_before)
            );
        }
        let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
        assert!(
            navigation.entries[0].engine.action().is_none(),
            "the target execution owner must block collect before the next queued back becomes a Core action"
        );
        drop(navigation);
    }

    #[derive(Debug, Eq, PartialEq)]
    enum BackTargetDriverUnverifiedObservation {
        Pending,
        Residual,
    }

    #[derive(Debug, Eq, PartialEq)]
    enum BackTargetDriverFailureStageObservation {
        PreReportIndeterminate(BackTargetDriverUnverifiedObservation),
        AwaitingReport(BackTargetDriverUnverifiedObservation),
        ReceiverMismatch(BackTargetDriverUnverifiedObservation),
        ConsumeMismatchFallback(BackTargetDriverUnverifiedObservation),
        PostReportPhysicalIndeterminateFailureCleanup(BackTargetDriverUnverifiedObservation),
        StagingDriftTargetOwnerOnly,
        DriverFailureStagingMismatch(BackTargetDriverUnverifiedObservation),
        Other,
    }

    fn observe_back_target_driver_failure_stage(
        entry: &RouterEntry,
    ) -> Option<BackTargetDriverFailureStageObservation> {
        if let Some(PendingBackTargetExecution::DriverFailureStagingMismatch(owner)) =
            entry.pending_back_target_execution.as_ref()
        {
            let unverified = match &owner.physical {
                BackTargetDriverUnverifiedPhysicalOwner::Pending(pending) => {
                    let _whole_pending = (&pending.ticket, &pending.final_task, &pending.branch);
                    BackTargetDriverUnverifiedObservation::Pending
                }
                BackTargetDriverUnverifiedPhysicalOwner::Residual(branch) => {
                    let _whole_residual = branch.realized_for_test();
                    BackTargetDriverUnverifiedObservation::Residual
                }
            };
            let _whole_mismatch = (
                &owner.task,
                owner.kind,
                owner.message,
                owner.evidence.observed,
                &owner.evidence.pairing,
            );
            if let Some(previous) = owner.previous.as_ref() {
                match previous {
                    BackTargetDriverStagingOwner::ResumeBlocked(previous) => {
                        let _whole_previous = previous;
                    }
                    BackTargetDriverStagingOwner::Driving(previous) => {
                        let _whole_previous = (&previous.history, &previous.continuation);
                    }
                    BackTargetDriverStagingOwner::Classifying(previous) => {
                        let _whole_previous = previous;
                    }
                    BackTargetDriverStagingOwner::Prepared(previous) => {
                        let _whole_previous = previous;
                    }
                    BackTargetDriverStagingOwner::CommitFailure(previous) => {
                        let _whole_previous = previous;
                    }
                    BackTargetDriverStagingOwner::ExistingMismatch(previous) => {
                        let _whole_previous = previous;
                    }
                    #[cfg(test)]
                    BackTargetDriverStagingOwner::TestDrift(previous) => {
                        let _whole_previous = (&previous.history, &previous.continuation);
                    }
                }
            }
            return Some(
                BackTargetDriverFailureStageObservation::DriverFailureStagingMismatch(unverified),
            );
        }
        #[cfg(test)]
        if let Some(PendingBackTargetExecution::DriverFailureStagingDrift(owner)) =
            entry.pending_back_target_execution.as_ref()
        {
            let _whole_target_owner = (&owner.history, &owner.continuation);
            return Some(BackTargetDriverFailureStageObservation::StagingDriftTargetOwnerOnly);
        }
        let Some(PendingBackTargetExecution::ResumeBlocked(
            PendingBackTargetResumeBlocked::DriverFailure(stage),
        )) = entry.pending_back_target_execution.as_ref()
        else {
            return None;
        };
        match stage {
            PendingBackTargetDriverFailure::PhysicalIndeterminate(owner) => {
                let _whole_owner = (
                    &owner.driving.history,
                    &owner.driving.continuation,
                    &owner.task,
                    &owner.physical.evidence,
                    owner.kind,
                    owner.message,
                );
                let unverified = match &owner.physical.original {
                    BackTargetDriverUnverifiedPhysicalOwner::Pending(pending) => {
                        let _whole_pending =
                            (&pending.ticket, &pending.final_task, &pending.branch);
                        BackTargetDriverUnverifiedObservation::Pending
                    }
                    BackTargetDriverUnverifiedPhysicalOwner::Residual(branch) => {
                        let _whole_residual = branch.realized_for_test();
                        BackTargetDriverUnverifiedObservation::Residual
                    }
                };
                Some(BackTargetDriverFailureStageObservation::PreReportIndeterminate(unverified))
            }
            PendingBackTargetDriverFailure::AwaitingReport(owner) => {
                let _whole_owner = (
                    &owner.driving.history,
                    &owner.driving.continuation,
                    &owner.task,
                    &owner.source,
                    owner.kind,
                    owner.message,
                );
                let unverified = match &owner.physical {
                    BackTargetDriverUnverifiedPhysicalOwner::Pending(pending) => {
                        let _whole_pending =
                            (&pending.ticket, &pending.final_task, &pending.branch);
                        BackTargetDriverUnverifiedObservation::Pending
                    }
                    BackTargetDriverUnverifiedPhysicalOwner::Residual(branch) => {
                        let _whole_residual = branch.realized_for_test();
                        BackTargetDriverUnverifiedObservation::Residual
                    }
                };
                Some(BackTargetDriverFailureStageObservation::AwaitingReport(
                    unverified,
                ))
            }
            PendingBackTargetDriverFailure::ReceiverMismatch(owner) => {
                let _whole_owner = (
                    &owner.driving.history,
                    &owner.driving.continuation,
                    &owner.task,
                    owner.kind,
                    owner.message,
                    &owner.mismatch,
                );
                let unverified = match &owner.physical {
                    BackTargetDriverUnverifiedPhysicalOwner::Pending(pending) => {
                        let _whole_pending =
                            (&pending.ticket, &pending.final_task, &pending.branch);
                        BackTargetDriverUnverifiedObservation::Pending
                    }
                    BackTargetDriverUnverifiedPhysicalOwner::Residual(branch) => {
                        let _whole_residual = branch.realized_for_test();
                        BackTargetDriverUnverifiedObservation::Residual
                    }
                };
                Some(BackTargetDriverFailureStageObservation::ReceiverMismatch(
                    unverified,
                ))
            }
            PendingBackTargetDriverFailure::ConsumeMismatch(owner) => {
                let _whole_owner = (
                    &owner.source.frozen,
                    &owner.history,
                    &owner.outcome,
                    &owner.mismatch,
                );
                let unverified = match &owner.physical {
                    BackTargetDriverUnverifiedPhysicalOwner::Pending(pending) => {
                        let _whole_pending =
                            (&pending.ticket, &pending.final_task, &pending.branch);
                        BackTargetDriverUnverifiedObservation::Pending
                    }
                    BackTargetDriverUnverifiedPhysicalOwner::Residual(branch) => {
                        let _whole_residual = branch.realized_for_test();
                        BackTargetDriverUnverifiedObservation::Residual
                    }
                };
                if matches!(
                    &owner.outcome,
                    BackTargetDriverFailureCoreOutcome::Fallback(_)
                ) {
                    Some(
                        BackTargetDriverFailureStageObservation::ConsumeMismatchFallback(
                            unverified,
                        ),
                    )
                } else {
                    Some(BackTargetDriverFailureStageObservation::Other)
                }
            }
            PendingBackTargetDriverFailure::PostReportPhysicalIndeterminate(owner) => {
                let _whole_owner = (&owner.source.frozen, &owner.history);
                let unverified = match &owner.physical {
                    BackTargetDriverUnverifiedPhysicalOwner::Pending(pending) => {
                        let _whole_pending =
                            (&pending.ticket, &pending.final_task, &pending.branch);
                        BackTargetDriverUnverifiedObservation::Pending
                    }
                    BackTargetDriverUnverifiedPhysicalOwner::Residual(branch) => {
                        let _whole_residual = branch.realized_for_test();
                        BackTargetDriverUnverifiedObservation::Residual
                    }
                };
                if matches!(
                    &owner.outcome,
                    BackTargetDriverFailureCoreOutcome::FailureCleanup(_)
                ) {
                    Some(
                        BackTargetDriverFailureStageObservation::PostReportPhysicalIndeterminateFailureCleanup(
                            unverified,
                        ),
                    )
                } else {
                    Some(BackTargetDriverFailureStageObservation::Other)
                }
            }
            _ => Some(BackTargetDriverFailureStageObservation::Other),
        }
    }

    #[test]
    fn back_target_driver_failure_exact_task_claim_blocks_zero_physical_report() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let router =
            install_atomic_router_at_pattern(&mut app, "back-target-task-claim-zero-red", "/:id");
        app.update();
        for location in ["/a", "/b"] {
            let request = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .unwrap();
            run_updates_until_succeeded(&mut app, request);
        }
        let _back = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(router)
            .expect("the real active route has one predecessor");

        let task = {
            let mut navigation = app.world_mut().resource_mut::<RouterNavigation>();
            let entry = &mut navigation.entries[0];
            let bound = take_real_bound_back_target(entry);
            let BackTargetResumeOutcome::Resumed {
                start: BackTargetStart::Ready(resume),
                retirement,
            } = resume_bound_back_target(entry, bound)
            else {
                panic!("the exact target must return its real root action")
            };
            drop(retirement);
            let (action, history, continuation) = resume.into_parts();
            let BackTargetResumeAction::FrameTask(task) = action else {
                panic!("the changed root target must begin with one real FrameTask")
            };
            entry.pending_back_target_execution = Some(PendingBackTargetExecution::Driving(
                PendingBackTargetDriving {
                    history,
                    continuation,
                },
            ));
            task
        };

        let residual = app.world_mut().spawn_empty().id();
        let manifest = ComponentManifest::new([
            app.world()
                .components()
                .component_id::<RouteOwnershipSeal>()
                .expect("the active branch registers ownership seals"),
            app.world()
                .components()
                .component_id::<FrameLifecycle>()
                .expect("the active branch registers frame lifecycle"),
        ]);
        let seal = {
            let mut registry = app.world_mut().resource_mut::<RouteEntityRegistry>();
            let seal = registry.issue_seal();
            registry
                .register(
                    residual,
                    RegistryOwner::Committed(EntityOwner::FrameOutput {
                        frame: task.frame().clone(),
                        output: u64::MAX,
                        local_index: usize::MAX,
                    }),
                    seal,
                    manifest,
                    EntityLifecycle::PreparedInert,
                )
                .unwrap();
            seal
        };
        app.world_mut().entity_mut(residual).insert((
            RouteOwnershipSeal::new(seal),
            FrameLifecycle(EntityLifecycle::PreparedInert),
        ));

        publish_snapshots_system(app.world_mut());
        let engine_before = app.world().resource::<RouterNavigation>().entries[0]
            .engine
            .snapshot();
        let history_before = app.world().resource::<RouterNavigation>().entries[0]
            .engine
            .history()
            .clone();
        let registry_before = app
            .world()
            .resource::<RouteEntityRegistry>()
            .records()
            .to_vec();
        let public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(router)
            .unwrap()
            .clone();

        app.world_mut().resource_scope(
            |world, mut navigation: bevy_ecs::change_detection::Mut<RouterNavigation>| {
                assert!(matches!(
                    route_back_target_frame_failure(
                        world,
                        &mut navigation.entries[0],
                        BackTargetDriverUnverifiedPhysicalOwner::Pending(PendingCommit::new()),
                        task,
                        ViewFailureKind::Build,
                        "exact task-owned residual must block zero physical",
                    ),
                    RouteBackTargetFrameFailureOutcome::Handled
                ));
            },
        );
        publish_snapshots_system(app.world_mut());

        let navigation = app.world().resource::<RouterNavigation>();
        let entry = &navigation.entries[0];
        assert_eq!(
            observe_back_target_driver_failure_stage(entry),
            Some(
                BackTargetDriverFailureStageObservation::PreReportIndeterminate(
                    BackTargetDriverUnverifiedObservation::Pending,
                )
            ),
            "an exact task-owned Entity must prevent Pending from becoming ProvenZero"
        );
        assert_eq!(entry.engine.snapshot(), engine_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(
            app.world().resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(
            app.world()
                .resource::<RouterSnapshots>()
                .get(router)
                .unwrap(),
            &public_before
        );
        assert!(cleanup_claim_has_exact_authority(
            app.world(),
            &registry_before
                .iter()
                .find(|record| record.entity() == residual)
                .unwrap()
                .claim()
        ));
    }

    #[test]
    fn back_target_driver_failure_registry_only_residual_safe_stops_pre_report_indeterminate() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let fail_next = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let router = install_armable_back_failure_router(
            &mut app,
            "back-target-driver-registry-only-indeterminate-red",
            fail_next.clone(),
        );
        app.update();
        for location in ["/a", "/b"] {
            let request = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .unwrap();
            run_updates_until_succeeded(&mut app, request);
        }

        let active_root_frame = app.world().resource::<RouterNavigation>().entries[0]
            .active
            .as_ref()
            .unwrap()
            .frames()[0]
            .frame()
            .clone();
        let registry_only_residual = app.world_mut().spawn_empty().id();
        assert!(app.world_mut().despawn(registry_only_residual));
        assert!(app.world().get_entity(registry_only_residual).is_err());
        {
            let mut registry = app.world_mut().resource_mut::<RouteEntityRegistry>();
            let owner = RegistryOwner::Committed(EntityOwner::FrameOutput {
                frame: active_root_frame,
                output: u64::MAX,
                local_index: usize::MAX,
            });
            assert!(
                registry
                    .records()
                    .iter()
                    .all(|record| !record.owner().conflicts_with(&owner)),
                "the registry-only fixture requires a unique active-root FrameOutput owner"
            );
            let seal = registry.issue_seal();
            registry
                .register(
                    registry_only_residual,
                    owner,
                    seal,
                    ComponentManifest::new(Vec::new()),
                    EntityLifecycle::Active,
                )
                .unwrap();
        }

        let (active_before, history_before, protected_before) = {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let active = entry.active.as_ref().unwrap();
            let mut protected = entry
                .active
                .as_ref()
                .unwrap()
                .frames()
                .iter()
                .flat_map(|frame| frame.claims().map(|claim| claim.entity()))
                .collect::<Vec<_>>();
            let host = entry.host.as_ref().unwrap();
            protected.extend([host.host, host.top_slot]);
            protected.sort_by_key(|entity| entity.to_bits());
            protected.dedup();
            (
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>(),
                entry.engine.history().clone(),
                protected
                    .into_iter()
                    .map(|entity| (entity, nested_protected_fingerprint(app.world(), entity)))
                    .collect::<Vec<_>>(),
            )
        };
        let registry_before = app
            .world()
            .resource::<RouteEntityRegistry>()
            .records()
            .to_vec();
        let public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(router)
            .unwrap()
            .clone();

        fail_next.store(true, Ordering::Release);
        let back = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(router)
            .expect("the real active route has one predecessor");
        for _ in 0..4 {
            app.update();
            let calls = app.world().resource::<RouterNavigation>().entries[0]
                .back_target_driver_failure_dispatch_calls
                .load(Ordering::Relaxed);
            if calls > 0 {
                break;
            }
        }

        let navigation = app.world().resource::<RouterNavigation>();
        let entry = &navigation.entries[0];
        assert_eq!(
            entry
                .back_target_driver_failure_dispatch_calls
                .load(Ordering::Relaxed),
            1,
            "the armed real driver failure must reach the sole target failure dispatcher"
        );
        assert_eq!(entry.engine.history(), &history_before);
        assert!(matches!(
            entry.engine.request(back).unwrap().status(),
            RequestStatus::Running(NavigationPhase::ApplyingFrame(_))
        ));
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert_eq!(
            app.world().resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(
            entry.active.as_ref().map(|active| {
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>()
            }),
            Some(active_before),
            "the pre-report safe-stop must preserve the real active branch"
        );
        assert!(app.world().get_entity(registry_only_residual).is_err());
        for (entity, before) in &protected_before {
            assert_eq!(
                &nested_protected_fingerprint(app.world(), *entity),
                before,
                "the pre-report safe-stop must preserve every active/protected entity"
            );
        }
        let public_after = app.world().resource::<RouterSnapshots>();
        let router_after = public_after.get(router).unwrap();
        assert_eq!(router_after.active(), public_before.active());
        assert_eq!(router_after.history(), public_before.history());
        assert_eq!(router_after.cleanup(), public_before.cleanup());
        assert!(matches!(
            public_after.request(router, back),
            crate::snapshots::RequestLookup::Found(snapshot)
                if matches!(
                    snapshot.status(),
                    RequestStatus::Running(NavigationPhase::ApplyingFrame(_))
                )
        ));
        assert_eq!(
            observe_back_target_driver_failure_stage(entry),
            Some(
                BackTargetDriverFailureStageObservation::PreReportIndeterminate(
                    BackTargetDriverUnverifiedObservation::Pending,
                )
            ),
            "a registry-only residual must keep the whole real Pending owner in entry-owned pre-report Indeterminate; current scaffold instead leaves an Unaccepted reportable Residual"
        );
    }

    #[test]
    fn back_target_driver_failure_staging_mismatch_does_not_fall_through_generic_report() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let fail_next = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let router = install_armable_back_failure_router(
            &mut app,
            "back-target-driver-staging-mismatch-red",
            fail_next.clone(),
        );
        app.update();
        for location in ["/a", "/b"] {
            let request = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .unwrap();
            run_updates_until_succeeded(&mut app, request);
        }

        let (active_before, history_before, protected_before) = {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let active = entry.active.as_ref().unwrap();
            let mut protected = active
                .frames()
                .iter()
                .flat_map(|frame| frame.claims().map(|claim| claim.entity()))
                .collect::<Vec<_>>();
            let host = entry.host.as_ref().unwrap();
            protected.extend([host.host, host.top_slot]);
            protected.sort_by_key(|entity| entity.to_bits());
            protected.dedup();
            (
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>(),
                entry.engine.history().clone(),
                protected
                    .into_iter()
                    .map(|entity| (entity, nested_protected_fingerprint(app.world(), entity)))
                    .collect::<Vec<_>>(),
            )
        };
        let registry_before = app
            .world()
            .resource::<RouteEntityRegistry>()
            .records()
            .to_vec();
        let public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(router)
            .unwrap()
            .clone();

        app.world_mut().resource_mut::<RouterNavigation>().entries[0]
            .back_target_driver_staging_drift_armed = true;
        fail_next.store(true, Ordering::Release);
        let back = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(router)
            .expect("the real active route has one predecessor");
        for _ in 0..4 {
            app.update();
            if !fail_next.load(Ordering::Acquire) {
                break;
            }
        }

        assert!(
            !fail_next.load(Ordering::Acquire),
            "the real armable driver must consume the failure input"
        );
        let navigation = app.world().resource::<RouterNavigation>();
        let entry = &navigation.entries[0];
        let staging = observe_back_target_driver_failure_stage(entry);
        assert!(
            matches!(
                staging,
                Some(
                    BackTargetDriverFailureStageObservation::StagingDriftTargetOwnerOnly
                        | BackTargetDriverFailureStageObservation::DriverFailureStagingMismatch(
                            BackTargetDriverUnverifiedObservation::Pending
                        )
                )
            ),
            "the predicate-input seam must retain the original target owner"
        );
        let request = entry.engine.request(back).unwrap();
        let status = request.status();
        assert!(
            matches!(
                status,
                RequestStatus::Running(NavigationPhase::ApplyingFrame(_))
            ),
            "a target staging mismatch must stop before generic report mutation; observed {status:?}"
        );
        assert_eq!(entry.engine.history(), &history_before);
        assert!(entry.pending_failed_branch.is_none());
        assert!(entry.cleanup_ledger.is_none());
        assert_eq!(
            app.world().resource::<RouteEntityRegistry>().records(),
            registry_before,
            "a target staging mismatch must not mutate the physical registry"
        );
        assert_eq!(
            entry.active.as_ref().map(|active| {
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>()
            }),
            Some(active_before),
            "the original active branch must remain protected"
        );
        for (entity, before) in &protected_before {
            assert_eq!(
                &nested_protected_fingerprint(app.world(), *entity),
                before,
                "a target staging mismatch must preserve every protected Entity"
            );
        }
        let public_after = app.world().resource::<RouterSnapshots>();
        let router_after = public_after.get(router).unwrap();
        assert_eq!(router_after.active(), public_before.active());
        assert_eq!(router_after.history(), public_before.history());
        assert_eq!(router_after.cleanup(), public_before.cleanup());
        assert!(matches!(
            public_after.request(router, back),
            crate::snapshots::RequestLookup::Found(snapshot)
                if matches!(
                    snapshot.status(),
                    RequestStatus::Running(NavigationPhase::ApplyingFrame(_))
                )
        ));
        assert_eq!(
            observe_back_target_driver_failure_stage(entry),
            Some(
                BackTargetDriverFailureStageObservation::DriverFailureStagingMismatch(
                    BackTargetDriverUnverifiedObservation::Pending,
                )
            ),
            "the original target owner and real PendingCommit/task owners must remain together in one typed safe-stop"
        );
    }

    #[test]
    fn back_target_root_missing_driver_routes_pending_owner_before_generic_failure() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let label = "back-target-root-missing-driver";
        let driver_key = ViewDriverKey::new(format!("{label}-driver")).unwrap();
        let router = install_atomic_router_at_pattern(&mut app, label, "/:id");
        app.update();
        for location in ["/a", "/b"] {
            let request = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .unwrap();
            run_updates_until_succeeded(&mut app, request);
        }

        let back = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(router)
            .expect("the real active route has one predecessor");
        collect_navigation_system(app.world_mut());
        {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            assert!(entry.pending_bound_back_resolution.is_none());
            assert!(entry.pending_back_target_execution.is_none());
            assert!(
                entry
                    .back_capacity_reservations
                    .iter()
                    .any(|(request, _)| *request == back),
                "collection alone must retain the exact Back capacity before same-call dispatch"
            );
        }
        let world_before = authority_world_fingerprint(app.world());
        let (active_before, history_before, protected_before) = {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let active = entry.active.as_ref().unwrap();
            let mut protected = active
                .frames()
                .iter()
                .flat_map(|frame| frame.claims().map(|claim| claim.entity()))
                .collect::<Vec<_>>();
            let host = entry.host.as_ref().unwrap();
            protected.extend([host.host, host.top_slot]);
            protected.sort_by_key(|entity| entity.to_bits());
            protected.dedup();
            (
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>(),
                entry.engine.history().clone(),
                protected
                    .into_iter()
                    .map(|entity| (entity, nested_protected_fingerprint(app.world(), entity)))
                    .collect::<Vec<_>>(),
            )
        };
        let registry_before = app
            .world()
            .resource::<RouteEntityRegistry>()
            .records()
            .to_vec();
        let public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(router)
            .unwrap()
            .clone();
        assert!(matches!(
            app.world()
                .resource::<RouterSnapshots>()
                .request(router, back),
            crate::snapshots::RequestLookup::Unknown
        ));

        app.world_mut().resource_mut::<RouterNavigation>().entries[0]
            .back_target_driver_report_receiver_drift_armed = true;
        let removed_driver = app
            .world_mut()
            .resource_mut::<ViewDriverStore>()
            .take_for_test(&driver_key)
            .expect("the real target driver must be installed before the missing-member input");

        drive_navigation_system(app.world_mut());

        app.world_mut()
            .resource_mut::<ViewDriverStore>()
            .restore_for_test(removed_driver);

        {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let stage = observe_back_target_driver_failure_stage(entry);
            assert_eq!(
                entry
                    .back_target_driver_failure_dispatch_calls
                    .load(Ordering::Relaxed),
                1,
                "a missing root Back target driver must enter the target-aware dispatcher before generic report_failed; observed {stage:?}"
            );
            assert!(entry.pending_failed_branch.is_none());
            assert_eq!(
                stage,
                Some(BackTargetDriverFailureStageObservation::ReceiverMismatch(
                    BackTargetDriverUnverifiedObservation::Pending,
                )),
                "report receiver drift must retain the complete Pending owner in the target-specific safe-stop"
            );
            assert!(!entry.back_target_driver_report_receiver_drift_armed);
            assert!(matches!(
                entry.engine.request(back).unwrap().status(),
                RequestStatus::Running(NavigationPhase::ApplyingFrame(_))
            ));
        }

        drive_navigation_system(app.world_mut());

        let navigation = app.world().resource::<RouterNavigation>();
        let entry = &navigation.entries[0];
        assert_eq!(
            entry
                .back_target_driver_failure_dispatch_calls
                .load(Ordering::Relaxed),
            1,
            "the saved receiver mismatch must block redispatch on the next schedule"
        );
        assert!(entry.pending_failed_branch.is_none());
        assert_eq!(
            observe_back_target_driver_failure_stage(entry),
            Some(BackTargetDriverFailureStageObservation::ReceiverMismatch(
                BackTargetDriverUnverifiedObservation::Pending,
            ))
        );
        assert_eq!(authority_world_fingerprint(app.world()), world_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(
            app.world().resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        assert_eq!(
            entry.active.as_ref().map(|active| {
                active
                    .frames()
                    .iter()
                    .map(|frame| frame.frame().clone())
                    .collect::<Vec<_>>()
            }),
            Some(active_before)
        );
        assert!(entry.cleanup_ledger.is_none());
        for (entity, before) in &protected_before {
            assert_eq!(&nested_protected_fingerprint(app.world(), *entity), before);
        }
        let public_after = app.world().resource::<RouterSnapshots>();
        assert_eq!(public_after.get(router).unwrap(), &public_before);
        assert!(matches!(
            public_after.request(router, back),
            crate::snapshots::RequestLookup::Unknown
        ));
    }

    #[test]
    fn back_target_child_outlet_failure_does_not_escape_to_generic_with_driving_owner() {
        let mut app = App::new();
        app.add_plugins(BevyUiRouterPlugin::default());
        let observed = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let driver_key = ViewDriverKey::new("nested-driver").unwrap();
        let item = RouteViewKey::new("item").unwrap();
        let router = install_nested_router(&mut app, observed.clone(), true);
        app.update();
        for location in ["/items/1", "/items/2"] {
            let request = app
                .world_mut()
                .resource_mut::<RouterNavigation>()
                .push(router, RouteLocation::new(location))
                .unwrap();
            run_updates_until_succeeded(&mut app, request);
        }

        {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let active = entry.active.as_ref().unwrap();
            assert_eq!(entry.engine.history().len(), 2);
            assert_eq!(
                entry.engine.history().current(),
                Some(&RouteLocation::new("/items/2"))
            );
            assert_eq!(active.frames().len(), 2);
            assert_eq!(active.child_slots().len(), 1);
            assert_eq!(
                view_integration::driver_key(&entry.views, &item),
                Some(&driver_key),
                "the real nested leaf must resolve through the driver removed below"
            );
        }

        let back = app
            .world_mut()
            .resource_mut::<RouterNavigation>()
            .back(router)
            .expect("the real nested history has one predecessor");
        collect_navigation_system(app.world_mut());
        {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            assert!(entry.pending_bound_back_resolution.is_none());
            assert!(entry.pending_back_target_execution.is_none());
            assert!(
                entry
                    .back_capacity_reservations
                    .iter()
                    .any(|(request, _)| *request == back),
                "collection alone must retain the exact Back capacity before same-call dispatch"
            );
        }

        let world_before = authority_world_fingerprint(app.world());
        let (active_before, history_before, protected_before) = {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let active = entry.active.as_ref().unwrap();
            let frames = active
                .frames()
                .iter()
                .map(|frame| frame.frame().clone())
                .collect::<Vec<_>>();
            let child_slots = active
                .child_slots()
                .iter()
                .map(|slot| {
                    (
                        slot.parent().clone(),
                        slot.outlet().clone(),
                        slot.slot_id(),
                        slot.slot(),
                        slot.slot_claim().clone(),
                    )
                })
                .collect::<Vec<_>>();
            let mut protected = active
                .claims()
                .map(|claim| claim.entity())
                .collect::<Vec<_>>();
            let host = entry.host.as_ref().unwrap();
            protected.extend([host.host, host.top_slot]);
            protected.sort_by_key(|entity| entity.to_bits());
            protected.dedup();
            (
                (frames, child_slots),
                entry.engine.history().clone(),
                protected
                    .into_iter()
                    .map(|entity| (entity, nested_protected_fingerprint(app.world(), entity)))
                    .collect::<Vec<_>>(),
            )
        };
        let registry_before = app
            .world()
            .resource::<RouteEntityRegistry>()
            .records()
            .to_vec();
        let public_before = app
            .world()
            .resource::<RouterSnapshots>()
            .get(router)
            .unwrap()
            .clone();
        let driver_calls_before = observed.lock().unwrap().clone();
        let removed_driver = app
            .world_mut()
            .resource_mut::<ViewDriverStore>()
            .take_for_test(&driver_key)
            .expect("the real nested driver must exist before the missing-member input");

        drive_navigation_system(app.world_mut());

        app.world_mut()
            .resource_mut::<ViewDriverStore>()
            .restore_for_test(removed_driver);

        {
            let navigation = app.world().resource::<RouterNavigation>();
            let entry = &navigation.entries[0];
            let stage = observe_back_target_driver_failure_stage(entry);
            assert_eq!(
                entry
                    .back_target_driver_failure_dispatch_calls
                    .load(Ordering::Relaxed),
                1,
                "the real ChildOutlet missing-driver failure must reach the target-aware dispatcher; observed {stage:?}"
            );
            assert!(
                entry.pending_failed_branch.is_none(),
                "a target-active ChildOutlet failure must not escape into generic failure cleanup"
            );
            assert_eq!(
                stage,
                Some(
                    BackTargetDriverFailureStageObservation::PreReportIndeterminate(
                        BackTargetDriverUnverifiedObservation::Pending,
                    )
                ),
                "the complete Driving, task and Pending owners must safe-stop until the outlet action slice"
            );
            assert!(matches!(
                entry.engine.request(back).unwrap().status(),
                RequestStatus::Running(NavigationPhase::ApplyingFrame(1))
            ));
        }

        drive_navigation_system(app.world_mut());

        let navigation = app.world().resource::<RouterNavigation>();
        let entry = &navigation.entries[0];
        assert_eq!(
            entry
                .back_target_driver_failure_dispatch_calls
                .load(Ordering::Relaxed),
            1,
            "the saved ChildOutlet safe-stop must block redispatch"
        );
        assert!(entry.pending_failed_branch.is_none());
        assert_eq!(
            observe_back_target_driver_failure_stage(entry),
            Some(
                BackTargetDriverFailureStageObservation::PreReportIndeterminate(
                    BackTargetDriverUnverifiedObservation::Pending,
                )
            )
        );
        assert_eq!(*observed.lock().unwrap(), driver_calls_before);
        assert_eq!(authority_world_fingerprint(app.world()), world_before);
        assert_eq!(entry.engine.history(), &history_before);
        assert_eq!(
            app.world().resource::<RouteEntityRegistry>().records(),
            registry_before
        );
        let active = entry.active.as_ref().unwrap();
        assert_eq!(
            active
                .frames()
                .iter()
                .map(|frame| frame.frame().clone())
                .collect::<Vec<_>>(),
            active_before.0
        );
        assert_eq!(
            active
                .child_slots()
                .iter()
                .map(|slot| {
                    (
                        slot.parent().clone(),
                        slot.outlet().clone(),
                        slot.slot_id(),
                        slot.slot(),
                        slot.slot_claim().clone(),
                    )
                })
                .collect::<Vec<_>>(),
            active_before.1
        );
        for (entity, before) in &protected_before {
            assert_eq!(&nested_protected_fingerprint(app.world(), *entity), before);
        }
        let public_after = app.world().resource::<RouterSnapshots>();
        assert_eq!(public_after.get(router).unwrap(), &public_before);
        assert!(matches!(
            public_after.request(router, back),
            crate::snapshots::RequestLookup::Unknown
        ));
    }

